package org.example.strategy_pattern.demo;import java.util.Arrays;// Strategy interfaceinterface SortStrategy {    void sort(int[] array);}// ConcreteStrategy A: Bubble Sortclass BubbleSortStrategy implements SortStrategy {    @Override    public void sort(int[] array) {        int n = array.length;        for (int i = 0; i < n - 1; i++) {            for (int j = 0; j < n - i - 1; j++) {                if (array[j] > array[j + 1]) {                    // swap array[j] và array[j+1]                    int temp = array[j];                    array[j] = array[j + 1];                    array[j + 1] = temp;                }            }        }        System.out.println("Sorted with Bubble Sort: " + Arrays.toString(array));    }}// ConcreteStrategy B: Quick Sortclass QuickSortStrategy implements SortStrategy {    @Override    public void sort(int[] array) {        quickSort(array, 0, array.length - 1);        System.out.println("Sorted with Quick Sort: " + Arrays.toString(array));    }    private void quickSort(int[] arr, int low, int high) {        if (low < high) {            int pi = partition(arr, low, high);            quickSort(arr, low, pi - 1);            quickSort(arr, pi + 1, high);        }    }    private int partition(int[] arr, int low, int high) {        int pivot = arr[high];        int i = low - 1;        for (int j = low; j < high; j++) {            if (arr[j] <= pivot) {                i++;                // swap arr[i] và arr[j]                int temp = arr[i];                arr[i] = arr[j];                arr[j] = temp;            }        }        // swap arr[i+1] và arr[high] (pivot)        int temp = arr[i + 1];        arr[i + 1] = arr[high];        arr[high] = temp;        return i + 1;    }}// Context: chứa tham chiếu đến một SortStrategyclass SortingContext {    private SortStrategy strategy;    // Khởi tạo với một strategy cụ thể    public SortingContext(SortStrategy strategy) {        this.strategy = strategy;    }    // Cho phép thay đổi strategy tại runtime    public void setStrategy(SortStrategy strategy) {        this.strategy = strategy;    }    // Thực hiện sắp xếp sử dụng strategy hiện tại    public void sort(int[] array) {        strategy.sort(array);    }}public class SortingDemoMain {    public static void main(String[] args) {        int[] data = {5, 2, 9, 1, 5, 6};        // Sử dụng Bubble Sort        SortingContext context = new SortingContext(new BubbleSortStrategy());        context.sort(Arrays.copyOf(data, data.length));        // Output: Sorted with Bubble Sort: [1, 2, 5, 5, 6, 9]        // Chuyển sang Quick Sort        context.setStrategy(new QuickSortStrategy());        context.sort(Arrays.copyOf(data, data.length));        // Output: Sorted with Quick Sort: [1, 2, 5, 5, 6, 9]    }}